const L={html:'HTML',css:'CSS',js:'JavaScript',tw:'Tailwind CSS',react:'React',ts:'TypeScript',vue:'Vue.js',next:'Next.js',node:'Node.js',express:'Express.js',mongo:'MongoDB',pg:'PostgreSQL',auth:'Next Auth',java:'Java',spring:'Spring Boot',git:'Git & GitHub',supa:'Supabase',stripe:'Stripe'};;
const ti = k => `<span class="ti">${IC[k]}</span>`;
const tag = k => `<span class="tag">${ti(k)}${L[k]}</span>`;

window.IC = IC;
window.L = L;
window.ti = ti;
window.tag = tag;

(() => {
  const still = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const orbEl=document.getElementById('orb');
const rings=[1,.62].map(s=>{const r=document.createElement('div');r.className='ring';orbEl.appendChild(r);return[r,s]});
const G0=['html','css','js','tw','react','ts','vue','next'],G1=['node','express','mongo','pg','auth','java','spring','git'];
const chips=[G0,G1].flatMap((g,ri)=>g.map((key,i)=>{const c=document.createElement('div');c.className='chip';c.innerHTML=ti(key)+L[key];orbEl.appendChild(c);return{c,ri,i,n:g.length}}));
function orb(t){
  const rx=Math.min(orbEl.clientWidth*.44,430),ry=rx*(rx<250?.4:.3);
  rings.forEach(([r,s])=>{r.style.width=rx*2*s+'px';r.style.height=ry*2*s+'px'});
  chips.forEach(o=>{const s=o.ri?.62:1,a=(still?0:t*(o.ri?-.3:.22))+o.i*Math.PI*2/o.n,z=Math.sin(a),sc=.85+.2*z;
    o.c.style.transform=`translate(-50%,-50%) translate(${Math.cos(a)*rx*s}px,${z*ry*s}px) scale(${sc})`;o.c.style.opacity=.6+.4*(z+1)/2;o.c.style.zIndex=z>0?3:0});
}

  function loopOrbit(t) {
    orb(t * 0.001);
    requestAnimationFrame(loopOrbit);
  }
  requestAnimationFrame(loopOrbit);

})();
